from __future__ import annotations

from pathlib import Path
import base64
import hashlib
import zlib

ROOT = Path(__file__).resolve().parent
TAB = ROOT / "dashboard" / "src" / "pages" / "inventory" / "TabTransfers.tsx"
DOMAIN_DIR = ROOT / "dashboard" / "src" / "pages" / "inventory" / "transfers"

EXPECTED_TAB_SHA256 = 'afd6a3b26a92242645582b0ef672d4559a81410e40a4699dbd87112be3e8c5ad'
PAYLOADS = {'types.ts': '', 'constants.ts': '', 'parsers.ts': '', 'utils.ts': '', '__TAB__': ''}


def fail(message: str) -> None:
    raise SystemExit(f"PATCH_ABORTED: {message}")


def normalize(text: str) -> str:
    return text.replace("\r\n", "\n")


def sha256_text(text: str) -> str:
    return hashlib.sha256(normalize(text).encode("utf-8")).hexdigest()


def decode_payload(value: str) -> str:
    return zlib.decompress(base64.b64decode(value)).decode("utf-8")


if not TAB.exists():
    fail("TabTransfers.tsx missing.")

tab_now = normalize(TAB.read_text(encoding="utf-8"))
new_tab = decode_payload(PAYLOADS["__TAB__"])

already_split = (
    './transfers/types' in tab_now
    and './transfers/parsers' in tab_now
    and './transfers/constants' in tab_now
    and './transfers/utils' in tab_now
)

if not already_split and sha256_text(tab_now) != EXPECTED_TAB_SHA256:
    fail(
        "TabTransfers.tsx differs from the exact post-hardening baseline. "
        f"Current SHA256={sha256_text(tab_now)}"
    )

DOMAIN_DIR.mkdir(parents=True, exist_ok=True)

for name in ("types.ts", "constants.ts", "parsers.ts", "utils.ts"):
    target = DOMAIN_DIR / name
    expected = decode_payload(PAYLOADS[name])

    if target.exists():
        current = normalize(target.read_text(encoding="utf-8"))
        if current != expected:
            fail(f"{name} already exists with different content.")
        print(f"UNCHANGED={name}")
    else:
        target.write_text(expected, encoding="utf-8")
        print(f"CREATED={name}")

if already_split:
    if tab_now != new_tab:
        fail("TabTransfers.tsx is partially split but does not match expected output.")
    print("UNCHANGED=TabTransfers.tsx")
else:
    TAB.write_text(new_tab, encoding="utf-8")
    print("PATCHED=TabTransfers.tsx")


# Structural gates: this stage is deliberately behavior-preserving.
tab = normalize(TAB.read_text(encoding="utf-8"))
types = normalize((DOMAIN_DIR / "types.ts").read_text(encoding="utf-8"))
constants = normalize((DOMAIN_DIR / "constants.ts").read_text(encoding="utf-8"))
parsers = normalize((DOMAIN_DIR / "parsers.ts").read_text(encoding="utf-8"))
utils = normalize((DOMAIN_DIR / "utils.ts").read_text(encoding="utf-8"))

checks = {
    "DOMAIN_TYPES_EXTRACTED": (
        "export interface WarehouseTransferListItem" in types
        and "export interface TransferDraftItem" in types
        and "export interface TransferOverrideOptions" in types
    ),
    "DOMAIN_CONSTANTS_EXTRACTED": (
        "export const STATUS_META" in constants
        and "export const TRANSFER_STATUSES" in constants
    ),
    "RUNTIME_PARSERS_EXTRACTED": (
        "export const parseTransferPage" in parsers
        and "export const parseTransferDetail" in parsers
        and "export const parseOverrideOptions" in parsers
    ),
    "PURE_UTILS_EXTRACTED": (
        "export const totalDraftPacks" in utils
        and "export const getMutationMessage" in utils
        and "export const formatDate" in utils
    ),
    "TAB_IMPORTS_DOMAIN": (
        'from "./transfers/types"' in tab
        and 'from "./transfers/parsers"' in tab
        and 'from "./transfers/constants"' in tab
        and 'from "./transfers/utils"' in tab
    ),
    "TAB_NO_DUPLICATE_DOMAIN_TYPES": (
        "interface WarehouseTransferListItem" not in tab
        and "interface TransferDraftItem" not in tab
        and "type TransferStatus =" not in tab
    ),
    "TAB_NO_DUPLICATE_PARSERS": (
        "const parseTransfer =" not in tab
        and "const parseOverrideOptions =" not in tab
    ),
    "API_ENDPOINTS_PRESERVED": all(
        endpoint in tab
        for endpoint in (
            "/warehouse/unified/transfers",
            "/warehouse/unified/transfer/locations",
            "/warehouse/unified/transfer/source-inventory",
            "/warehouse/unified/transfer/override-options",
            "/warehouse/unified/transfer/dispatch",
            "/warehouse/unified/transfer/receive",
        )
    ),
    "IDEMPOTENCY_PRESERVED": (
        "request_id: createRequestId" in tab
        and "request_id: actionRequestId" in tab
    ),
    "LOCATION_IDS_PRESERVED": (
        "source_location_id: sourceLocationId" in tab
        and "destination_location_id: destinationLocationId" in tab
        and "location_id: String(locationId)" in tab
    ),
    "FEFO_OVERRIDE_PRESERVED": (
        "is_fefo_override: true" in tab
        and "override_batch_id:" in tab
        and "override_reason_id:" in tab
    ),
    "SCALABILITY_PRESERVED": (
        "sourceProductsNextCursor" in tab
        and "transferLocationSearchInput" in tab
    ),
    "NO_COMPANY_ID_IN_TAB": "company_id" not in tab,
    "NO_EXPLICIT_ANY": (
        ": any" not in tab
        and ": any" not in parsers
        and "any[]" not in tab
        and "any[]" not in parsers
    ),
}

failed = [name for name, ok in checks.items() if not ok]
if failed:
    fail(f"Static verification failed: {failed}")

print("TRANSFER_DOMAIN_TYPES_BOUNDARY=OK")
print("TRANSFER_RUNTIME_CONTRACTS_BOUNDARY=OK")
print("TRANSFER_PURE_UTILS_BOUNDARY=OK")
print("TRANSFER_ENDPOINTS_BEHAVIOR_PRESERVED=OK")
print("TRANSFER_IDEMPOTENCY_BEHAVIOR_PRESERVED=OK")
print("TRANSFER_LOCATION_SCOPE_BEHAVIOR_PRESERVED=OK")
print("TRANSFER_FEFO_BEHAVIOR_PRESERVED=OK")
print("TRANSFER_MODULARIZE_STAGE1=OK")
